insert into public.academy_course_structures
    (app_slug, tier, structure, content_version)
insert into public.academy_quiz_questions
    (app_slug, tier, scope, module_key, ord, prompt, options, answer_index, explanation)
values
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 1, 'On the published wells_fight ladder W-0 makes 3522.516744485 lb/d alone on its header and 3137.891322295 lb/d sharing it with two others. What about W-0 is different between those two runs?', '["Its inflow curve was rescaled by the solver so that the three wells on the header sum to what the common trunk can pass.", "Its flowline conductance was cut to carry the extra friction the two later wells put into the shared trunk.", "Nothing at all. The reservoir pressure, the shape of the inflow curve and the flowline conductance are the same in both runs, and the only thing that moved is the header pressure the well has to push against.", "Its reservoir pressure was drawn down by the neighbouring wells over the period the ladder covers."]'::jsonb, 2, 'The header climbs 416.314057 psi across the ladder and every well already on it makes strictly less, so the 384.625422 lb/d W-0 gives up, 10.919052 percent of itself, is what a shared header costs.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 2, 'Total delivered on the published wells_fight ladder rises from 3522.516744 lb/d with one well on the header to 9076.922229 lb/d with three, so the two that joined bought 5554.405485 lb/d. What kind of number is that?', '["Less than the pair would be worth at the header they found when they arrived, because their arrival is what raised it.", "A disagreement between the oracle ladder and the engine re-run of the same case, since Newton and Gauss-Seidel stop on criteria that are not comparable.", "Mass the trunk cannot pass, held back at the header and recovered later once the separator pressure is backed off, which is the one lever that helps every well at once.", "The error made by adding surface volumes across pressures rather than adding mass rates in lb/d, which the module header warns hides for a long time."]'::jsonb, 0, 'W-0 alone made 3522.516744485 lb/d and makes 3137.891322295 lb/d once they are on, so the header rise takes something from every well including the two that caused it.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 3, 'Every flow in these two modules is carried as a mass rate in lb/d. Why does the module header insist on that rather than on surface volumes?', '["Because a Vogel inflow is written in mass units and converting it would need a fluid model this module does not carry anywhere.", "Because the branch conductances are published in lb/d per root psi, and a flow has to be reported in the units of whatever conductance produced it.", "Because a sink takes whatever arrives at a fixed pressure, and a boundary condition can only be balanced in the unit it was written in.", "Surface volumes do not add across pressures, so mixing two of them is a mistake that hides for a long time."]'::jsonb, 3, 'Mass in equals mass out on every branch by construction, and a barrel at 1257.276513629 psia is not the same quantity as a barrel at 265 psia.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 4, 'What is MIN_PRESSURE_PSIA, which the module carries as 14.7 psia?', '["The pressure the solver starts every unknown node at before the first Newton step, which is why an answer can depend on the initial guess.", "A floor no node is allowed below, and the only opinion the module has about the size of a pressure.", "The value a delivery point falls back to when it is supplied with no pressure of its own, in place of refusing the drawing outright.", "The atmospheric datum the module subtracts on the way out, since a reported node pressure is absolute rather than gauge."]'::jsonb, 1, 'Pressures here are absolute psia and never gauge, so 14.7 psia is a floor rather than a datum, a default or a starting guess.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 5, 'A study returns a bore in inches, an equivalent length in ft and a wall rating in psi. Which of the six functions produced them?', '["diagnose, which reads a solved answer for its bottleneck, its biggest drop, its backflows and its dead legs, and reports the line geometry behind each of them.", "buildNetwork, since every branch is indexed before the solve.", "pipeSchedule.js, which is a published table and two closed forms and knows nothing about a network.", "propagateStreams, which walks the solved flow directions."]'::jsonb, 2, 'Nothing in pipeSchedule.js iterates and nothing in it knows there is a network, so a bore out of the table is only an input to a branch relation somebody else writes.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 6, 'Of the six functions in these two modules, how many iterate?', '["Three, because buildNetwork walks the drawing repeatedly looking for a route to a delivery point and propagateStreams walks every branch again after the solve.", "One, solveNetwork, which runs Newton on the nodal mass balance with a numerically differenced Jacobian and a line search.", "Two, since checkConservation sweeps the wells and the delivery points.", "None, because the branch relation is a callback and the caller owns the iteration."]'::jsonb, 1, 'Every defect this course teaches is either inside that one iteration or in something that was never compared against it.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 7, 'The pipe hydraulics along a branch and the well inflow are both handed in from outside. What does that make them?', '["Published fixtures shipped inside the engine package, in the same sense as a row of the pipe table or the resistance coefficient of a fully open gate valve.", "Defaults the module falls back to when a branch is drawn with no relation on it, which is what lets an incomplete drawing be solved at all.", "Optional refinements replaced by a linear resistance when absent.", "Callbacks the consumer supplies, so this module can only be wrong about a line by being handed a relation that is wrong."]'::jsonb, 3, 'The module owns neither relation, which is also why there is no temperature, no compressibility and no transient anywhere in it.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 8, 'AGBADA-2 is a Vogel well with a qmax of 8100 lb/d at 2750 psia on a flowline of 275 lb/d per root psi, run alone against the separator at 265 psia. Which parts of that answer were found rather than typed in?', '["The wellhead of 892.889543025 psia and the rate of 6890.874160167 lb/d, and with them the line drop and the drawdown.", "The qmax of 8100 lb/d, which the module reads off the Vogel relation once it knows the boundary pressure the well is solved against.", "The flowline conductance of 275 lb/d per root psi, fitted to the line drop.", "The separator pressure of 265 psia, settled by what the flowlines deliver."]'::jsonb, 0, 'One curve falls and one rises, they cross once, and the crossing is the wellhead, which is where the 627.889543025 psi line drop and the 1857.110457 psi drawdown come from.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 9, 'The teaching network comes back converged with a reported residual of 1.546141e-11 lb/d, and checkConservation on the same answer reports a gap of 345.000000000 lb/d. Which of the two is a check on the answer?', '["The residual, since it is the worst nodal imbalance anywhere in the network while a gap only compares two totals.", "The gap, because the reported residual and the converged flag were both produced by the very iteration whose answer is in question, while the gap is computed separately from what the wells put in against what the delivery points took out.", "Both, since they are one measurement written twice, once as a maximum over nodes and once as a sum over the boundary.", "Neither, since the gap is computed from the same solved pressures and inherits whatever error those pressures carry."]'::jsonb, 1, 'Produced comes back as 13300.677150912 lb/d against delivered 12955.677150912 lb/d, relative 0.025938529000, and solveNetwork never calls checkConservation.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 10, 'DEFAULT_TOLERANCE_LB_D is 0.000001 and its own comment says Newton stops when the worst nodal imbalance is below it, in lb/d. What does the solver actually stop at?', '["Exactly that constant, in lb/d, which is why a solve of a large system costs more Newton steps than a small one before it can meet the same mass target.", "The larger of that constant and the movement in the pressures between two successive Newton steps, so the criterion sits on the answer rather than on the balance.", "That constant divided by the 7 unknown pressures.", "That constant multiplied by a scale it computes for itself, which is a different number and one the caller never sees."]'::jsonb, 3, 'The name promises a mass and what runs is a mass times a scale, so the documented default is looser than its own name says.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 11, 'buildNetwork turns away eleven distinct malformed drawings. What does it do with them?', '["It repairs what it can, such as tying a stranded node to the nearest header, and refuses only where the repair would be ambiguous.", "It solves them anyway and attaches a warning, on the same footing as a pinned node or a solve that ran its iteration cap.", "It refuses each one with ok false and a sentence naming the offending node or branch, it repairs none of them, and no pressure is computed for a drawing that failed.", "It returns a partial result over the part of the drawing that is well formed, so one bad branch does not hold up a large network."]'::jsonb, 2, 'A drawing mistake is not a network with a small problem, so solving it anyway would produce a confident answer about a system that does not exist.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 12, 'A caller asks the pipe table for a size it does not carry. What comes back from scheduleRow(5, ''40'')?', '["Null, and never the nearest row the table does have, because a nearby row is a different pipe.", "The NPS 4 schedule 40 row, since the table interpolates between the two published sizes on either side of the size that was asked for.", "A refusal object carrying ok false and a sentence naming the size, in the shape buildNetwork uses for a malformed drawing.", "NaN, which is what every missed lookup in the file returns."]'::jsonb, 0, 'scheduleRow(6, ''160'') is null the same way, and a caller who wanted an approximation can ask for one on purpose.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 13, 'What does fittingK(''elbow90'') resolve to, and why is that identifier the dangerous one?', '["0.3, the long radius value, because the module resolves an ambiguous elbow identifier to the gentler of the two entries that it publishes.", "NaN, and it is dangerous because elbow90 is what a careful person types when the table holds elbow90LR and elbow90Std.", "Null, the way a missing pipe size does, so a numeric test catches it.", "A refusal naming it, the way an unknown fitting in a list does."]'::jsonb, 1, 'NaN carries through arithmetic without complaint, while a fitting list holding an unknown identifier refuses whole rather than dropping the term.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 14, 'AGBADA-12 alone on its flowline is allocated 985 lb/d on a line that cannot pass more than 640 lb/d. The result is converged in 4 iterations with a reported residual of 0.0000e+0 lb/d and pinned t4. Why is that a warning rather than a refusal?', '["Because the drawing is well formed, so no refusal path in buildNetwork can run at all.", "Because an allocation is a legal inflow and a capacity limit is a legal branch relation, so both callbacks met their contracts.", "Because a residual of 0.0000e+0 lb/d is exact, and a solve that lands on its target has nothing left to report.", "Because a pinned node is reported as a fact about the answer, and the shortfall it creates never reaches the number the converged flag is tested against."]'::jsonb, 3, 'checkConservation on that same answer reports a gap of 3.450000e+2 lb/d, relative 3.502538e-1, and neither the flag nor the residual says so.'),
  ('network', 'beginner', 'module', 'm01-a-gathering-system', 15, 'Which of these does this module carry no representation of at all?', '["A node whose pressure was supplied, which has to be written into the branch relations on either side of it instead of being carried as a node.", "A branch whose flow runs against the way it was drawn, which is why a drawn from and to is refused as a claim about direction.", "Temperature, slugging, holdup, transients of any kind and compressibility along a branch.", "A well held to a fixed rate, since an inflow must fall with pressure."]'::jsonb, 2, 'Every equation here is steady state and mass in equals mass out on every branch by construction, so no pump, compressor or choke exists as a node kind either.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 1, 'NPS 6 schedule 40 is 6.625 in on the outside and 6.065 in through. What is the 6 in NPS 6?', '["The bore at schedule 40 rounded to the nearest inch, which is why the schedule 80 row of that same size reports a smaller number through the middle.", "A name for the size, and it is neither the outside diameter nor the bore in either schedule the table carries.", "The outside diameter rounded down to a whole inch of steel.", "The wall class, from which both of the bores follow."]'::jsonb, 1, 'Schedule 80 on the same size bores 5.761 in, so a hydraulic calculation run on the nominal number uses a diameter that appears nowhere in the row it came from.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 2, 'NPS 8 goes from schedule 40 to schedule 80. What moves and what does not?', '["The bore is held and the outside diameter grows, since a schedule is a pressure class and pressure wants metal added on the outside.", "Both diameters shrink together, so the flow area falls while the wall stays where the table put it.", "The wall thickens and the bore is unchanged, so all of the extra steel is carried outward.", "The outside diameter stays 8.625 in, the wall goes from 0.322 in to 0.5 in and the bore falls from 7.981 in to 7.625 in, which is 0.356000 in of bore and 8.722219 percent of the flow area."]'::jsonb, 3, 'A heavier schedule is a thicker wall and a smaller bore on the same outside diameter, which is the whole idea of a schedule.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 3, 'Every row of the pipe table carries an outside diameter, a wall and a bore, although the third is arithmetically the first two. Why is the third one there?', '["Because the redundancy is the table''s only self check, and there is no Python referee for this module anywhere.", "Because the bore is measured rather than computed, so the published figure carries a manufacturing tolerance the arithmetic cannot reproduce.", "Because a hydraulic calculation needs the bore and a wall rating needs the outside diameter, so both are stored to save the caller an arithmetic step.", "Because a schedule number resolves to a wall only for the sizes the table ships, so the bore is what a caller falls back to."]'::jsonb, 0, 'The module header says a transcription error in any one of the three makes the outside diameter less two walls fail to equal the bore, and that is the whole of the check.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 4, 'Run the outside diameter less two walls against the published bore as strict equality, in double precision, across all 12 rows. What happens?', '["All 12 hold exactly, which is why the shipped gate is able to assert equality rather than closeness on every row of the table.", "Several fail, because the published bores are rounded to three decimals while the walls carry more digits than that rounding can support.", "1 of them fails, NPS 6 schedule 40, by -8.8818e-16 in.", "Every row fails at the last bit of a double."]'::jsonb, 2, 'That residual is the last bit of a double and it is the largest residual anywhere in the table. Every other row of the twelve is exactly zero.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 5, 'The shipped assertion does not use equality. It passes anything within 5.0000e-4 in of the published bore. What does that band let through?', '["Nothing of consequence, because a transcription error changes a digit before the third decimal and lands far outside a band that narrow.", "Only the one row whose residual is already nonzero, since the band was set to the size of the largest residual the table contains.", "A wall error but not a bore error, because the assertion is written against the bore and the wall enters it twice.", "A bore typed as 6.0654 in where the row says 6.065 in, which is a real transcription error rather than floating point noise."]'::jsonb, 3, 'The band is 5.6295e+11 times wider than the largest residual the table actually carries, so it is wider than the error class the redundancy exists to catch.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 6, 'A strict check at 1e-12 in would be true of every one of the twelve rows. What does that say about the assertion that runs today?', '["That the strict check would be unsafe, because the rows carry floating point noise at the last bit and a check that tight would fail on ordinary arithmetic.", "That a check whose band is larger than the error class it hunts is not a check, and this one is twelve orders looser than it could be.", "That the two are equivalent, since both pass every published row.", "That the table should carry only two of the three numbers."]'::jsonb, 1, 'The noise being hidden is one bit wide at -8.8818e-16 in, and the tolerance chosen to hide it is 5.6295e+11 times wider than that bit.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 7, 'Barlow is P = 2 S t f / D. Which diameter goes into the D?', '["The bore, since the pressure acts on the inside surface of the pipe and it is the inside surface that sets the hoop load the wall carries.", "The mean diameter, which keeps a thick wall conservative.", "The outside diameter, so the gate case uses 6.625 in and not the 6.065 in bore.", "Whichever the caller supplies, since the module treats the diameter as an input and never looks up a table row of its own."]'::jsonb, 2, 'The outside diameter is the only dimension in the denominator, so doubling it to 13.25 in halves the rating to 1582.369811 psi.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 8, 'What reaches a wall rating out of this module?', '["An outside diameter, a wall, a yield and a design factor, and nothing else at all.", "Those four together with the bore, which enters through the ratio of the wall to the bore and is why the table publishes all three numbers.", "Those four together with the fluid and the operating temperature, which the design factor is derived from rather than supplied alongside.", "Those four together with the roughness class of the line, since a corroding surface is what makes a wall allowance necessary in the first place."]'::jsonb, 0, 'The gate case is 6.625 in on a 0.28 in wall in X52 at 52000 psi at a design factor of 0.72, and it rates 3164.739623 psi. Change the fluid or the year it was laid and the answer is still 3164.739623 psi.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 9, 'Run the gate pipe with no design factor supplied. What comes back?', '["A refusal, since the module never defaults a design factor and refusing is what it does everywhere else that an input is missing.", "NaN, in the same way an unknown grade resolves to NaN, so a caller who never tests for it prints it and carries it onward.", "The same 3164.739623 psi, because the design factor is applied by the caller when the rating is written onto a drawing.", "The bare hoop stress of 4395.471698 psi, which is 1.388889 times the rated pressure and is not a number anyone may operate to."]'::jsonb, 3, 'A wall at yield is a wall about to fail, so a bare hoop stress describes a limit rather than a pressure to work to.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 10, 'The gate pipe rates 3164.739623 psi. Double the wall to 0.56 in and it rates 6329.479245 psi. Why exactly double?', '["Because the bore closes as the wall thickens, and the rating rises with the ratio of the wall to the bore rather than with the wall on its own.", "Because twice the wall is twice the metal carrying the load.", "Because Barlow is linear in the wall, and the wall is the only dimension in the numerator.", "Because the yield of 52000 psi is quoted per unit wall thickness, so twice the wall carries twice the stress at the same design factor."]'::jsonb, 2, 'The outside diameter works the same way from the denominator, so doubling it to 13.25 in halves the rating instead.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 11, 'The same 6.625 in pipe with the same 0.28 in wall at the same design factor of 0.72 is walked through every grade the module ships. What is the range?', '["2130.113208 psi up to 7536.231884 psi, because the top of the grade range is quoted as a bare hoop stress rather than at a design factor.", "2130.113208 psi at gradeB up to 3955.924528 psi at x65, and only the steel moved.", "It cannot be walked, because a grade is tied to a schedule.", "The rating does not move, since grade sets the wall the table publishes."]'::jsonb, 1, 'Grade is the cheapest lever on a rating on paper, which is why it is the one most often quoted without the design factor that goes with it.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 12, 'The teaching NPS 8 schedule 80 line in x65 is rated at design factors of 0.4, 0.5, 0.72, 0.8 and 1. What moved down that column?', '["Nothing physical. Same steel, same wall, same outside diameter and same table row.", "The wall, because a design factor of 1 corresponds to the nominal wall while the lower factors are quoted against a corroded wall allowance.", "The yield, since a design factor is applied to the published yield of 65000 psi before the rating is formed and therefore selects a different steel.", "The bore of 7.625 in, which falls as the design factor rises and takes the flow area with it while the outside diameter is held."]'::jsonb, 0, 'The rating runs from 3014.492754 psi to 7536.231884 psi because somebody typed a different number for a rule.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 13, 'Compare the reach of the two inputs: grade across everything the module ships on one pipe, against the design factor alone on the teaching line. Which moves the answer further?', '["Grade, since it is the only input that changes the steel and the steel is what carries the load the rating describes.", "Neither, because a design factor is dimensionless and a yield is in psi, so their effects on a rating are not comparable quantities.", "The wall, which is absent from both sweeps and is the only one of the four inputs the rating is linear in.", "The design factor, which runs the teaching line from 3014.492754 psi to 7536.231884 psi where the whole grade range on the gate pipe spans 2130.113208 psi to 3955.924528 psi."]'::jsonb, 3, 'The regulatory input has the longer reach and it is the one most often inherited from a spreadsheet whose author is no longer around.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 14, 'gradeYield(''x55'') resolves to NaN. Why does the module decline to fall back on a nearby grade?', '["Because NaN is the standard return of every lookup in the file, so the pipe table also returns NaN for a size it does not have.", "Because a grade identifier is validated against the schedule row it was requested with, and x55 does not appear in any of the twelve rows.", "Because a rating quoted against the wrong yield reads exactly like a rating, and a missing yield or a zero wall returns NaN for the same reason.", "Because a fallback would need an interpolation between 52000 psi and 60000 psi, and a yield is not a quantity anyone may interpolate."]'::jsonb, 2, 'NaN carries through arithmetic without complaint, so the refusal is one a caller who never tests for it will print.'),
  ('network', 'beginner', 'module', 'm02-the-line-and-what-it-holds', 15, 'Two ratings from two sources are written side by side and they differ. What can be read off that difference?', '["The steel, since the wall and the outside diameter are fixed by the schedule row and a design factor is a dimensionless multiplier that cancels between two ratings of the same line.", "Nothing on its own, because the gap may be steel, wall, diameter or a jurisdiction and the rating carries none of them.", "The wall, once the outside diameters are known.", "The design factor, once the grades are known."]'::jsonb, 1, 'On one 6.625 in pipe with one 0.28 in wall at a design factor of 0.72, gradeB rates 2130.113208 psi and x65 rates 3955.924528 psi, and only there is the difference really steel.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 1, 'A fitting in this table has no length. What does it have?', '["A pressure drop in psi, quoted at the reference rate the table was measured at.", "A length in ft, published per nominal size, which the caller sums over the list.", "A resistance coefficient, a pure multiplier on one velocity head, which knows nothing about the bore, the fluid or the rate and is the whole of what the table holds about that fitting.", "A friction factor of its own, which the calculation blends with the pipe''s."]'::jsonb, 2, 'A globe valve is 10 and a fully open ball valve is 0.05 on the same bore with nothing else different, and neither number carries a diameter in it.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 2, 'The table publishes elbow90LR at 0.3 and elbow90Std at 0.75. What separates them?', '["The radius of the turn and nothing else.", "The size, since the long radius entry is the one used above NPS 6 and the standard entry below it, which is why the coefficients differ by so much.", "The material, because a long radius bend is drawn from pipe while a standard elbow is a cast fitting with a rougher internal surface.", "The direction, since a long radius elbow is priced for flow taken straight through and a standard elbow for flow turned onto a branch."]'::jsonb, 0, 'Both are 90 degree elbows on the same turn, and the table prices the gentler one at less than half the standard one.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 3, 'The table lists suddenExit at 1, an exit into a vessel. Why is a coefficient charged where no fitting is bolted?', '["Because the vessel is a node in the network and the module charges a coefficient at every node kind it accepts, including a sink.", "Because the entry into the vessel is a sudden expansion and the table has no separate entry for an expansion, so the exit coefficient stands in for one.", "Because a swing check at 2 usually sits just upstream of a vessel.", "Because the velocity head leaving the pipe is lost the same way a fitting loses it."]'::jsonb, 3, 'A teeBranch is 1 as well, so the module prices an exit at the same coefficient as flow turned onto the branch of a tee.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 4, 'Every valve entry in the table ends in the words fully open. What follows from that?', '["A valve part way shut is handled by interpolating between the gate value of 0.15 and the globe value of 10, which is why both are published on the same list.", "A throttling valve is not in this module and cannot be reached by scaling one of the published coefficients.", "The coefficients are conservative, since a fully open valve is the worst case for a pressure loss and everything else sits below it on the same curve.", "The equivalent length calculation asks for a valve position alongside the bore and the friction factor, and refuses when it is not given one."]'::jsonb, 1, 'There is no entry for any other position, so a throttled valve is a thing the module leaves out rather than a thing it approximates.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 5, 'A fitting list carries an identifier the table does not publish. What does the equivalent length calculation do with the rest of the list?', '["It sums the entries it recognises and reports a length with a warning naming the identifier it could not price, in the way a pinned node is reported.", "It substitutes the nearest coefficient the table does publish, so a reducer is priced as a sudden exit at 1 and the caller is told which substitution ran.", "Nothing. It refuses the whole list with ok false and the sentence No resistance coefficient for reducer.", "It returns a length built from the recognised entries and a sum of K carrying NaN, so the two returned numbers disagree with each other."]'::jsonb, 2, 'Dropping a term would quietly understate the list, so the calculation refuses whole rather than pricing part of it.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 6, 'Four long radius elbows and two gate valves sit on a 6.065 in bore at a friction factor of 0.018. What comes back?', '["A sum of K of 1.500000 and a pressure drop in psi, since the point of an equivalent length is to reach a drop the caller can add to a line.", "A sum of K of 1.500000 only, since no measured run was given.", "An equivalent length per fitting, six figures, which the caller adds because two of the six are valves and four are bends.", "A sum of K of 1.500000 and an equivalent length of 42.118056 ft."]'::jsonb, 3, 'That is the length of straight 6.065 in pipe, at that friction factor, which costs the same pressure as those six fittings.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 7, 'The same four elbows and two gate valves are run across the published schedule 40 bores at a friction factor of 0.018. What happens to the answer?', '["It rises with the bore, from 14.354167 ft on 2.067 in to 104.166667 ft on 15 in, because the bore is the only geometry in the formula.", "It falls with the bore, since a wider pipe loses less per foot and the fittings therefore stand in for fewer feet of it.", "It holds, because the fittings entered only through their coefficients.", "It rises with the square of the bore, following the flow area."]'::jsonb, 0, 'An equivalent length written on a datasheet is a figure about one particular pipe, and the fitting is the only part of it that travels.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 8, 'The same six fittings on the same 6.065 in bore give 42.118056 ft at a friction factor of 0.018 and 63.177083 ft at 0.012. Why is the smoother line worth more feet?', '["Because a lower friction factor means a higher velocity for the same rate, and the fittings are priced in velocity heads, so each one costs more on the smoother line.", "Because the pipe got cheaper per foot, so it takes 1.500000 times as many feet of it to lose what the fittings lose.", "Because the fittings themselves are smoother too, and the table''s coefficients are quoted against a reference roughness.", "Because a smoother pipe carries more mass, and an equivalent length scales with what the line delivers."]'::jsonb, 1, 'The friction factor sits in the denominator for that reason and no other, so a fitting has no equivalent length until a pipe has been named.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 9, 'The module ships absolute roughnesses of 0.0018 in, 0.006 in, 0.0002 in and 0.00006 in. What does the equivalent length calculation do with them?', '["It picks a roughness from the schedule row and solves a friction factor.", "It bounds the friction factor the caller supplies and warns outside it.", "It converts the roughness into a relative roughness on the supplied bore and iterates a friction factor correlation to convergence from it.", "Nothing at all. It asks the caller for a friction factor and refuses without one."]'::jsonb, 3, 'Nothing in the file iterates and a friction factor correlation is an iteration, so a missing one gives An equivalent length needs a bore and a friction factor.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 10, 'The teaching line carries three standard elbows, two branch tees, four ball valves and one globe valve on a 7.625 in bore at a friction factor of 0.017. How is its 540.104167 ft distributed?', '["The single globe valve is 69.204152 percent of it and 373.774510 ft, and the other nine fittings share what is left.", "Evenly across the ten items, since a sum of K of 14.450000 divided over the list is what a length is built from.", "The three standard elbows dominate at 15.570934 percent, because they are the most numerous heavy item on the list.", "The two branch tees dominate at 13.840830 percent, since a tee taken on the branch is the largest coefficient in the published table."]'::jsonb, 0, 'One entry in the published table reaches double figures and it is on this line, at 10 against a fully open ball valve at 0.05.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 11, 'Four ball valves on the teaching line are four of the ten items. What are they worth?', '["A quarter of the length, because four items out of ten weighted by their coefficients is roughly what a valve count buys on any list.", "More than the three elbows, since there are four of them.", "1.384083 percent of the resistance and 7.475490 ft of the 540.104167 ft.", "Nothing measurable, because a fully open ball valve resolves to NaN and is dropped from the sum before the length is formed."]'::jsonb, 2, 'Count is what an engineer can see on a drawing and it is not what anything costs. Four items at 0.05 each are 0.200000 of a sum of K of 14.450000.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 12, 'Two lines carry the identical fitting list, one with the globe valve at the wellhead and one with it at the separator. What do the two equivalent lengths come to?', '["They differ, because the calculation walks the list in order and applies each coefficient to the pressure remaining after the ones ahead of it, which is why the order is part of the input.", "The same 540.104167 ft, because the sum of K is a sum and nothing in the file knows where anything sits.", "They differ by the length of pipe between the two positions.", "Neither can be computed without the measured run between the fittings."]'::jsonb, 1, 'Position is refused along with interaction: nothing in the file knows that two fittings close together behave differently from two far apart.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 13, 'A fitting is thirty diameters of pipe is applied once to the whole published list, whose sum of K is 1.500000. What friction factor is that rule assuming?', '["0.018, the friction factor the gate case was run at.", "0.02, which is the value most often quoted with the rule and the one that puts the same published set at 75.000000 diameters of pipe.", "None, since a diameters count is pure geometry.", "0.05, because the count in diameters is the sum of K over the friction factor."]'::jsonb, 3, 'The engine puts the same set at 83.333333 diameters at a friction factor of 0.018, so a fixed diameters count is a friction factor written in a disguise.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 14, 'The same thirty diameters rule can be read as thirty per fitting or thirty over the whole list. What does the reading change?', '["Only the size of the disagreement, since both readings sit below the engine and the whole list version is simply the more conservative of the two.", "Nothing, because six fittings summing to a sum of K of 1.500000 come to the same count either way once the coefficients are weighted.", "The sign of the bias, so the reading has to be stated before the rule is compared with anything.", "The bore the count is applied to, since a per fitting reading is charged on the bore local to each fitting and a whole list reading on the largest."]'::jsonb, 2, 'Read over the whole list it gives 15.162500 ft against the engine 42.118056 ft and understates by nearly three times, and read per fitting across six fittings it overstates instead.'),
  ('network', 'beginner', 'module', 'm03-fittings-as-pipe', 15, 'Read as diameters of pipe, the published fitting list runs 150.000000 at a friction factor of 0.010 and 50.000000 at 0.030. What does that say about a fixed diameters count?', '["That there is no single count for a fitting set. There is one count per friction factor, and a fixed rule is exactly one of them without saying which.", "That the count belongs to the coarsest row, since a rule of thumb is meant to be conservative and 50.000000 is the smallest of the six.", "That the count is only defined once a bore is named, since the sweep was run on one bore.", "That the two ends of the sweep are outside the range any real line runs at."]'::jsonb, 0, 'The coarsest row is as honest as the finest, and quoting a rule of thumb is quoting a friction factor without admitting to it.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 1, 'Five branches meet at the north manifold of AGBADA WEST. What statement does the module make there?', '["That the five flows share the manifold pressure in proportion to the conductance of each branch tied into it.", "That what arrives leaves, and nothing else. A junction injects nothing, stores nothing and has no capacity, no inventory and no inflow of its own.", "That the manifold holds whatever the wells deliver above what the trunk can pass, which is where a header builds inventory.", "That the largest of the five sets the manifold pressure and the others are solved against it."]'::jsonb, 1, 'Mass is the currency and a junction balances it exactly, so the five flows at ha have to add to nothing.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 2, 'The separator on AGBADA WEST sits at 265 psia. What is special about that number in the drawing?', '["It is the lowest pressure in the answer, which is what makes it the boundary rather than an ordinary node with a low pressure on it.", "It is the initial guess for the sink, refined by the solve once the four flowlines have settled what they can deliver into it.", "It is a warning threshold, since no node may sit below 14.7 psia.", "It is the only pressure anybody supplied, and it is what the other seven are solved against."]'::jsonb, 3, 'A sink has a fixed pressure and takes whatever arrives, so 8 nodes with 1 delivery point leaves 7 unknown pressures.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 3, 'buildNetwork reports 7 unknown pressures on AGBADA WEST, which carries 4 wells. What are the other three?', '["The three junctions, since an unknown is any node whose pressure nobody supplied.", "The three branches that form the loop, because a loop leaves the split between its two paths undetermined and each undetermined split is counted as an unknown.", "Three of the eight branches, since a branch flow is unknown until the pressures at both of its ends are settled and only five of the eight are fixed.", "The separator counted three times, once for each junction that can reach it, since the boundary enters every balance that touches it."]'::jsonb, 0, 'Each unknown node contributes one mass balance, so the solve is 7 equations in 7 pressures and the count is not a count of wells.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 4, 'A drawing carries a node whose kind is written compressor. What comes back?', '["It is accepted as a junction, since a compressor neither produces nor consumes mass and a junction is exactly the node kind that injects nothing.", "It is accepted with a warning, on the same footing as a pinned node, because the topology is still readable and only the equipment is unknown.", "A refusal: Node \"K-1\" has kind \"compressor\", which is not one of well, junction, sink.", "It is accepted and its pressure rise is read from the branch relations either side of it, which is where the module expects equipment to live."]'::jsonb, 2, 'There is no pump, compressor or choke as a node kind, so a device between two nodes has to be written into the branch relation between them or left out and said so.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 5, 'In a tree every branch flow is fixed by the flows downstream of it. What is different once the drawing carries a loop?', '["The two paths carry equal mass by symmetry, so the split is fixed and it is the pressures at the two ends that stop being determined.", "The split between the two paths is decided by the pressures, and the pressures are decided by the split.", "The flows still follow from downstream, but the loop adds one extra unknown pressure for each parallel path that has to be indexed alongside the nodes.", "The loop is broken before the solve by cutting the slackest leg."]'::jsonb, 1, 'The north manifold reaches the trunk tee straight down the north bypass and again through the crosslink and the loop leg, and that is why an iteration exists.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 6, 'AGBADA WEST is drawn with a from and a to on each of its eight branches. What is that pair?', '["A labelling convention rather than a claim. The drawing was made before anybody solved anything, and which way mass goes on a branch is a property of the answer.", "A statement of direction the module enforces, refusing any solved flow that comes out against it.", "The order the branch is indexed in, which sets the sign of its entry in the Jacobian.", "A hint the solver uses to pick an initial guess, discarded once the first step is taken."]'::jsonb, 0, 'The build refuses a branch that starts and ends at the same node and a branch that ends at a node that is not there, and it has no opinion at all about direction.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 7, 'What is refused when a drawing carries a node with no route to a delivery point?', '["Only that node, which is dropped from the index.", "Nothing, since the node just gets pinned where it sits.", "Nothing at build time, because a route to a delivery point is a property of the solved flow directions rather than of the drawing.", "The whole drawing, with the sentence naming Manifold B and saying nothing sets its pressure."]'::jsonb, 3, 'A network with a well that cannot reach a delivery point is a drawing mistake rather than a network with a small problem.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 8, 'The obvious repair for a stranded node is to hang it off the nearest header. What is wrong with that?', '["It changes the unknown count, so the solve is no longer the same size as the drawing it was read from and the index will not line up with the node array.", "It is refused anyway, because a branch added after the build is not in the index and the solve reads the index rather than the drawing.", "It invents a branch with a conductance nobody measured, and every pressure downstream of it is then an answer about a system that does not exist.", "It moves the node below MIN_PRESSURE_PSIA."]'::jsonb, 2, 'Every one of the eleven refusals has an obvious repair, and every repair invents a fact about the field.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 9, 'The eleven refusals fall into two families. What separates them?', '["Five are about nodes and six are about branches, which is why the sentence for each one names either a node or a branch and never both.", "Five ask whether the drawing can carry production at all, and six ask whether it can be read.", "Five come back before the index is built and six come back after it.", "Five carry a name in the sentence and six do not."]'::jsonb, 1, 'Both families come back the same way, ok false with a sentence naming the offending node or branch, with no partial result and no pressures.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 10, 'A build comes back ok true. What has that established?', '["That every well has a route to the delivery point and that the flows the solve will later produce will therefore add to nothing at every junction.", "That the node and branch counts agree with the drawing and that the unknown count matches the number of pressures the solve is about to report.", "That the topology is sound, which is the one condition under which a later converged flag can be read as a statement about the numbers.", "That the drawing could be indexed, and nothing whatever about mass balancing."]'::jsonb, 3, 'The same word comes back true from a solve that hit its iteration cap, so ok is not a verdict on any number.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 11, 'The gate''s own pinning fixture is a well whose inflow is a constant 2000 lb/d on a branch whose flow is a constant 1000 lb/d. What does the module return?', '["ok true and converged true after 1 iteration, pinned w, a reported residual of 0.000000e+0 lb/d, and the warning that the node carried nothing and nothing depended on its pressure.", "ok false, since a constant inflow is not monotone decreasing in pressure and the module requires that of every inflow it accepts.", "ok true with a reported residual of 1000.000000 lb/d, which is the imbalance the pinned node carries by itself.", "ok true and pinned w, with the mass that cannot leave reported as a backflow on the branch."]'::jsonb, 0, 'checkConservation on that same answer reports produced 2000.000000 lb/d against delivered 1000.000000 lb/d, a gap of 1000.000000 lb/d, relative 0.500000000.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 12, 'buildNetwork returns the unknowns of AGBADA WEST in the order t1, t2, t3, t4, ha, hb, hc. Why is sep missing from that list?', '["Because a sink carries only one branch, and the module drops any node with a single branch on it from the index it hands to the solve.", "Because a sink is indexed separately from the wells and the junctions, in its own delivery point list, and is solved after the seven unknowns have settled.", "Because its pressure was supplied, and an unknown is a node whose pressure nobody typed.", "Because a sink is written into the branch relation instead."]'::jsonb, 2, 'Eight nodes with one delivery point leaves seven, and seven is the size of the problem the solve is about to run.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 13, 'The node array of the teaching network is reversed, which changes no physics at all. What moves?', '["Nothing at all, because the index is keyed on the node id rather than on the array position and the solve reads the index rather than the array.", "The unpinned pressures by at most 1.1369e-13 psia, and the pinned node by 5.4710e-9 psia.", "Every pressure by the same amount, since the pivot order changes.", "The branch flows but not the pressures, since the signs follow the array."]'::jsonb, 1, 'A bookkeeping order is allowed to be worth the last bits of a double, and the two numbers there are four orders apart under one label.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 14, 'What would take AGBADA WEST from 7 unknown pressures to 6 without taking any node out of the drawing?', '["Supplying a pressure at one more node, which turns it into a second delivery point the rest of the system is solved against.", "Removing one of the eight branches, since a branch carries one unknown flow.", "Shutting one of the four wells in, which takes its inflow out of the balance.", "Merging the loop tee into the trunk tee, since the two carry 3 branches each."]'::jsonb, 0, 'An unknown is a node whose pressure nobody supplied, so the count moves when a pressure is supplied and not when a branch or an inflow changes.'),
  ('network', 'beginner', 'module', 'm04-nodes-and-branches', 15, 'What do the refusals naming a duplicate id, a branch ending at a node that is not there and a node with no id have in common?', '["All three are recoverable, since the module can generate an identifier for anything that lacks one and drop a branch whose end does not resolve.", "All three are detected during the solve rather than the build, because an identifier is only consulted when a pressure is written back onto a node.", "All three concern the route to the delivery point.", "None of them is about pressure or flow. They are about whether the drawing can become a table at all."]'::jsonb, 3, 'An index cannot carry two rows under one name, a branch end has to resolve to a row, and a row with no name cannot be looked up downstream.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 1, 'A solo run puts one well on one flowline against one boundary. Which quantities did somebody type in?', '["The qmax, the reservoir pressure, the flowline conductance and the separator pressure of 265 psia.", "Those four together with the wellhead pressure, since a two node problem needs a pressure at each end before a branch relation between them can be evaluated at all.", "Only the separator pressure, since the inflow and the line are callbacks.", "Only the inflow, since the flowline is read from the pipe table."]'::jsonb, 0, 'A well node is the only row in the index once the separator''s pressure is supplied, so the wellhead and the rate are what comes out.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 2, 'AGBADA-9 has a qmax of 5750 lb/d at 2350 psia on a flowline of 198 lb/d per root psi. What does its solo run return?', '["A wellhead of 840.553310094 psia and its qmax of 5750 lb/d, since the qmax is the rate at the wellhead the solve settles on.", "A rate of 4750.157046765 lb/d, with the wellhead left as whatever the caller supplied it as before the run started.", "A wellhead of 840.553310094 psia and a rate of 4750.157046765 lb/d.", "A wellhead of 2350 psia, since a well on its own line is not drawn down by anything and sits at reservoir pressure."]'::jsonb, 2, 'Its line takes 575.553310094 psi to reach the separator, and 1509.446690 psi of the reservoir pressure is spent getting fluid to the wellhead at all.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 3, 'Why does a solo well have exactly one landing point rather than a range of them?', '["Because the solve is seeded at the separator pressure and walks upward, stopping at the first crossing it meets.", "Because the module requires the inflow to be monotone decreasing in pressure while the branch carries more mass for a bigger difference across it, so one curve falls, one rises and they cross once.", "Because a Vogel relation is a quadratic and a quadratic has exactly one root above the boundary pressure.", "Because the flowline conductance is a constant, which makes the line loss a straight line in the pressure."]'::jsonb, 1, 'Newton finds that crossing in 7 iterations on AGBADA-2, AGBADA-6 and AGBADA-9, which is what a two node problem should cost.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 4, 'AGBADA-2 carries a qmax of 8100 lb/d and its solo run makes 6890.874160167 lb/d. What is the difference?', '["The share of the deliverability the flowline conductance of 275 lb/d per root psi absorbs, which is why a slacker line would return a rate closer to the qmax.", "The difference between a rate at reservoir conditions and one at 265 psia.", "The allowance the module keeps back from every Vogel inflow so that the well stays inside the monotone decreasing band its contract asks for.", "A pressure the well has to spend. A qmax belongs to a flowing pressure of nothing and no well on a line ever sees it."]'::jsonb, 3, 'The drawdown from 2750 psia to a wellhead of 892.889543025 psia is 1857.110457 psi, and that is what the missing rate paid for.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 5, 'AGBADA-6 lands at a wellhead of 335.147329090 psia, the lowest of the three unallocated wells. Why so low?', '["Because it has the lowest qmax of the three at 3300 lb/d, and a smaller inflow puts less mass on the line and therefore lands nearer the boundary pressure.", "Because its reservoir pressure of 1650 psia is the lowest of the three, and a wellhead is the reservoir pressure less a drawdown that is much the same on every well.", "Because its line is slack enough to reach the separator for 70.147329090 psi.", "Because its conductance of 365 lb/d per root psi is the largest of the four, and a wellhead is set by the conductance rather than by what the line has to carry."]'::jsonb, 2, 'AGBADA-9 pays 575.553310094 psi on a 198 lb/d per root psi line for 4750.157046765 lb/d, and AGBADA-6 pays 70.147329090 psi for 3057.021085629 lb/d.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 6, 'AGBADA-6 carries 3057.021085629 lb/d for 70.147329090 psi and AGBADA-9 carries 4750.157046765 lb/d for 575.553310094 psi. Why is the second drop so much larger?', '["Because a turbulent branch drop goes with the square of the mass, so rather more mass down a much stiffer line costs a large multiple of the pressure.", "Because the two lines are different lengths, which the conductance does not carry.", "Because AGBADA-9 sits further from the separator, and the drop scales with distance.", "Because the drop follows the drawdown, and AGBADA-9 has the larger of the two."]'::jsonb, 0, 'The conductances are 365 and 198 lb/d per root psi, and a square law is what turns a modest difference in mass into that comparison.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 7, 'A colleague writes down a branch conductance of 275 and asks whether it is larger than one of 365. What has to be established first?', '["Which end of the branch the conductance was measured from, since a conductance is signed from the drawn from to the drawn to and reverses with the direction.", "The bore of each line, since a conductance folds a bore into it.", "The pressure difference each was quoted at, because a turbulent conductance is only constant over the band of differences it was fitted across.", "Which of the two units it is in, because lb/d per root psi and lb/d per psi are different quantities and never compare."]'::jsonb, 3, 'A turbulent branch carries lb/d per root psi and a linear branch carries lb/d per psi, and a conductance means nothing until somebody says which.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 8, 'Two linear branches of 200 and 300 lb/d per psi in series give a wellhead of 183.333333333 psia, and so does the single 120.000000000 lb/d per psi branch the reciprocal rule predicts. What does that establish?', '["That the two rules hold for any branch relation the module accepts, since the reduction is a property of the topology rather than of the relation on each branch.", "That the reciprocal rule and the parallel sum are exact for a linear branch, and for a linear branch only.", "That a turbulent branch can be reduced the same way once its conductance in lb/d per root psi is squared into the linear units first.", "That the solve is exact on a series of branches and iterative only where a loop is present, which is why the difference between the two runs is 0.0000e+0 psia."]'::jsonb, 1, 'The same two in parallel give 120.000000000 psia and so does a single branch of 500 lb/d per psi, and neither rule survives a turbulent branch.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 9, 'AGBADA-12''s solo run reports a residual of 0.0000e+0 lb/d and a conservation gap of 3.450000e+2 lb/d. Why are those two not in contradiction?', '["Because the residual is measured over the unpinned nodes only, and the node carrying the shortfall is the one that was pinned.", "Because the residual is in lb/d and the gap is the relative 3.502538e-1.", "Because the residual is taken before the last Newton step and the gap after it.", "Because a residual measures how far the pressures moved between iterations while a conservation gap measures mass, so a solve can be tight on one and loose on the other."]'::jsonb, 0, 'Its allocation of 985 lb/d sits on a line that passes only 640 lb/d, and the difference stops being counted.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 10, 'The Vogel relation for AGBADA-12 read at its solo wellhead of 303.714448989 psia gives 1938.321311203 lb/d. The solve reports 985.000000000 lb/d. Which is the well''s inflow?', '["The 1938.321311203 lb/d, since that is what the reservoir will deliver at that wellhead and an allocation is an operating instruction rather than an inflow.", "The 985.000000000 lb/d, because the solve evaluated the curve it was handed and a returned rate is by definition what the inflow gave.", "Neither on its own. The inflow handed in is the Vogel curve capped at the allocation, and 985.000000000 lb/d is where the cap binds.", "The 1938.321311203 lb/d, since only the flowline can cap a rate."]'::jsonb, 2, 'The rate came back because it was typed in as an allocation, not because the line could pass it.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 11, 'The module header asks that an inflow be monotone decreasing in pressure. What is a well held to a facility allocation?', '["Still monotone decreasing, since the allocation only clips the curve above the pressure at which it binds and the curve below that point is untouched.", "Outside the contract, which is why buildNetwork refuses a capped inflow with a sentence naming the node it was attached to.", "Monotone increasing above the binding pressure, since a well at its allocation is delivering the same mass against a rising wellhead.", "Monotone non-increasing, with a flat top over a whole band of pressures, and that flat top is exactly what makes its node pinnable."]'::jsonb, 3, 'Below the pressure where the allocation binds the node is perfectly live, and once the line saturates as well the node loses both its row and its column.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 12, 'For each solo well, add the drawdown and the line drop to the separator pressure of 265 psia. What comes back?', '["The wellhead pressure, since the drawdown is measured from the wellhead rather than from the reservoir and the line drop is measured from the separator.", "The reservoir pressure, since the two drops are the whole of what the reservoir pressure is spent on.", "The bottomhole flowing pressure, which sits between the two.", "Nothing meaningful, because a drawdown and a line drop are not additive."]'::jsonb, 1, 'AGBADA-12 has a drawdown of 1146.285551 psi and a line drop of 38.714448989 psi against a reservoir pressure of 1450 psia.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 13, 'The four AGBADA wells solved alone add to 15683.052292561 lb/d and the system they share produces 13300.677150912 lb/d. What is the 2382.375141650 lb/d between them?', '["The mass held at the header by the trunk, which reappears once the separator pressure is backed off and the header is allowed to fall.", "The difference between the reported production and what the delivery point took, which is the conservation gap the solve does not check.", "What the network costs, 15.190761959 percent, and no amount of single-well work recovers it.", "The share of the four solo rates that belongs to the one allocated well, whose 985.000000000 lb/d is counted in the solo column but not on the system."]'::jsonb, 2, 'A solo run never sees the header, so the shortfall is not visible from either column on its own.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 14, 'Ranked by percentage lost, the AGBADA wells run t2 at 24.162893177, t3 at 15.951269648, t1 at 12.857585591 and t4 at 0.000000000 percent. Ranked by rate on the system, t1 leads. What does the mismatch say?', '["That a well with little margin over the header has the least to give when the header rises, and an allocation meeting that ranks by rate never sees it.", "That the percentages are computed against different baselines, so the two rankings are not comparable quantities.", "That the wells with the stiffest flowlines lose the most, since a stiff line multiplies a header rise.", "That the ranking by loss follows the ranking by qmax, reversed."]'::jsonb, 0, 'AGBADA-6 gives up the largest share of itself at 24.162893177 percent while making the second least on the system at 2318.356346320 lb/d.'),
  ('network', 'beginner', 'module', 'm05-one-well-on-its-own', 15, 'AGBADA-12 loses 0.000000000 percent between its solo run and the system, and its wellhead rose 527.461813 psi, the largest rise of the four. How can both be true?', '["Its flowline conductance of 126 lb/d per root psi is the slackest of the four, so a large rise at the manifold reaches its wellhead almost undiminished.", "Its reservoir pressure of 1450 psia is the lowest of the four.", "A wellhead rise and a rate loss are independent quantities.", "Its allocation holds its reported rate at 985.000000000 lb/d in both columns while its flowline passes 640.000000000 lb/d of that."]'::jsonb, 3, 'The rise never reaches the reported rate because the cap binds above it, which is why no number in the solo columns warns anybody about the system answer.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 1, 'Why does the Associate order settle the line before anything is built or solved?', '["Because the solve reads the schedule row itself and will refuse a network whose branches carry no pipe.", "Because the pipe table has to be loaded before buildNetwork can index anything.", "Because a bore, a wall, a rating and a fitting count are quantities the system has before anything is solved together, and every one of them is an input to a branch relation the solve will be handed.", "Because a rating sets the boundary pressure the whole system is solved against."]'::jsonb, 2, 'Nothing in pipeSchedule.js iterates and nothing in it knows there is a network, so the line work and the network work never touch except through the numbers handed across.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 2, 'The order says to take the bore from the schedule row rather than computing it, then check it against the outside diameter less two walls. Why both?', '["Because the two disagree by more than a rounding on several rows, so the arithmetic value is the one to carry and the published bore is only there for a reader.", "Because the redundancy is the table''s only self check and running it is what catches a transcription error before it reaches a hydraulic calculation.", "Because a computed bore is exact and a published one is measured.", "Because the shipped gate checks one and not the other."]'::jsonb, 1, 'Run as strict equality across all 12 rows, 1 fails by -8.8818e-16 in, which is the last bit of a double rather than a bad row.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 3, 'The order treats a null out of the pipe table as an answer. What is the answer?', '["That the lookup failed for a reason the table does not report, so the caller should retry with the schedule spelled differently before concluding anything.", "That the size exists but the schedule does not, since a null distinguishes a missing schedule from a missing size in the way NaN distinguishes a missing grade.", "That the row exists and carries no bore, so the outside diameter less two walls has to be used in its place for anything downstream.", "That the table does not carry that size, and that no nearby row will be substituted for it."]'::jsonb, 3, 'A nearby row is a different pipe, and a caller who wanted an approximation can ask for one on purpose.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 4, 'Why does the order say to name the largest contributor to a fitting list before quoting the total?', '["Because one fitting can be most of the list, and a total hides which one.", "Because the coefficients are summed in the order the list was written and the largest term dominates the floating point error in the sum.", "Because the calculation refuses a list whose largest coefficient has not been identified, in the same way it refuses one with no bore.", "Because the largest coefficient sets the friction factor the rest of the list is converted at, so it has to be found before the length can be formed."]'::jsonb, 0, 'On a list summing to 14.450000, one globe valve at 10 is 69.204152 percent of it and 373.774510 ft of 540.104167 ft.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 5, 'The order says to convert a fitting list on the bore and friction factor of the line those fittings sit on, never one borrowed from elsewhere. What does borrowing cost?', '["Nothing on a length, since the fittings enter only through their coefficients, but it moves the sum of K away from 1.500000 and that is what the error shows up in.", "A rounding, since real friction factors are all close together.", "The whole of the difference between 42.118056 ft and 63.177083 ft on the same six fittings and the same 6.065 in bore.", "A refusal, because the calculation compares the supplied friction factor against the roughness class of the line and declines a mismatch."]'::jsonb, 2, 'The two answers differ by a factor of 1.500000 and nothing about the elbows or the valves changed between them.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 6, 'The order says that if the build refuses, the drawing is wrong. What is the instruction that follows?', '["Rebuild with the offending node removed, since the refusal names it and a network is solvable once every remaining node has a route to the boundary.", "Read the sentence and fix the drawing, rather than editing the input until the build passes.", "Supply the missing quantity as a default and record the default alongside the answer.", "Solve anyway and read the warnings, since a refusal and a warning are the same object."]'::jsonb, 1, 'A caller that edits the input until the build passes has moved a drawing error into the answer, where nothing names it.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 7, 'The order says to solve each well alone before solving them together, and to record the wellhead, the rate and the line drop for each. What is that triple for?', '["It is the initial guess the system solve is seeded with, which is why the order insists the solo runs come first and why the pinned pressures depend on it.", "It is the check on the system answer, since the solo rates have to add to what the system produces once the header rise has been subtracted from each.", "It is what the branch conductances are fitted to.", "It is what a single-well study would have handed you, so the distance from it to the system answer is what the network did."]'::jsonb, 3, 'The four AGBADA solo rates add to 15683.052292561 lb/d and the system produces 13300.677150912 lb/d, which is the 15.190761959 percent the network cost.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 8, 'Why does the order put reading every branch sign before reading anything downstream of it?', '["Because a drawn from and to is a labelling convention, and which way mass goes is a property of the answer.", "Because a branch whose solved flow runs against the drawing is refused, and the refusal has to be caught before a split is taken from the result.", "Because a flow sign decides the sign of its conductance.", "Because the solve indexes branches by their drawn direction, so a sign read late cannot be traced back to the branch it belongs to."]'::jsonb, 0, 'The drawing was made before anybody solved anything, so a direction, a split or a downstream reading taken from the arrow is taken from a label.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 9, 'The last step of the Associate order is to run checkConservation. Why is it a step at all?', '["Because it has to be run before diagnose, which reads the gap when it ranks a bottleneck and cannot report one without it.", "Because the solve calls it only when a node was pinned, and a network with nothing pinned therefore comes back with no gap reported on it.", "Because solveNetwork does not call it, so the number only exists if somebody asks for it.", "Because it is the function that turns a reported residual into a mass, since the residual is scaled by a factor the caller never sees."]'::jsonb, 2, 'On the teaching network it reports a gap of 345.000000000 lb/d, 2.593852900 percent of what the engine says was produced, under a reported residual of 1.546141e-11 lb/d.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 10, 'The tier closes on four questions to ask of every returned number. What are they?', '["Which iteration it came from, how many steps that iteration took, whether it moved between the last two steps, and how far it sits from the tolerance the caller asked for.", "Which of the six functions produced it, what unit it is in, whether that function had a way to refuse, and what checked it that was not the iteration that made it.", "Which node it belongs to, which branch carries it, whether it is signed, and which of the two conductance units it was formed with.", "Whether it is published, derived or teaching, whether it came from a golden case, whether an oracle saw it, and whether the gate asserts on it."]'::jsonb, 1, 'The habit is the most transferable thing in the course, and the fourth question is the one that separates a converged flag from a check.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 11, 'Where does the Associate tier hand over?', '["At the loop, because a tree can be added up by hand while a loop needs the split and the pressures settled together in one iteration.", "At the pinned node, because a pinned pressure is not determined by anything and cannot be read alongside the nodes that were actually solved.", "At the sign convention, since a backwards branch breaks the split.", "At the second well, because a rate on a shared header is not reachable from any single-well method."]'::jsonb, 3, 'W-0 makes 3522.516744485 lb/d alone on its header and 3137.891322295 lb/d sharing it, a loss of 384.625422 lb/d, 10.919052 percent of itself, while the header rises 416.314057 psi.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 12, 'The oracle committed 3137.891322295 lb/d for W-0 in the three well case and the engine lands 9.3905e-10 lb/d away from it. What does that agreement establish?', '["Something about the physics, because the two methods share no numerical machinery at all.", "Something about the code, since the engine was tuned until it reproduced the committed golden values within the tolerance the gate asserts.", "Something about the convergence criteria, since two solvers agreeing to that many digits must be stopping on the same measure of the same residual.", "Something about the tolerance, since the gap is the scaled target the solver actually stopped at rather than the tolerance the caller asked for."]'::jsonb, 0, 'The oracle sweeps node by node with a bracketed bisection and no Jacobian, while the engine runs Newton with a differenced Jacobian and a line search.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 13, 'What did these two modules never carry in the first place?', '["A way of refusing a malformed drawing, which is why the caller has to validate the topology before handing it in.", "A published table of any kind, since every number a branch needs arrives from the consumer.", "The pipe hydraulics and the well inflow, which are both callbacks, and with them any temperature, transient or compressibility.", "A boundary pressure, which the solve settles rather than being told."]'::jsonb, 2, 'Every equation is steady state and mass in equals mass out on every branch by construction, so no pump, compressor or choke exists as a node kind either.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 14, 'The tier says everything it can measure sits still. What does that mean?', '["That every quantity in the tier is a published constant rather than an engine return, which is why none of them carries an iteration count beside it.", "That a bore, a wall, a rating, a fitting count, a node kind, an index and one well against one boundary all exist before anything is solved together.", "That nothing in the tier changes with time, since the module is steady state.", "That nothing in the tier can move, since the design factor is the only input."]'::jsonb, 1, 'AGBADA-2 alone at 892.889543025 psia making 6890.874160167 lb/d is the last of them, and the second well is where quantities stop sitting still.'),
  ('network', 'beginner', 'module', 'm06-the-associate-reading', 15, 'What does a solo well answer establish, and what does it not?', '["It establishes a wellhead, a rate and a line drop against one boundary, and it says nothing about where any of the three sits once a neighbour is opened.", "It establishes the well''s deliverability, which is fixed, and says nothing about the line.", "It establishes the line''s conductance, and says nothing about the reservoir behind it.", "It establishes nothing at all, since the boundary pressure was supplied."]'::jsonb, 0, 'Every single-well study is run against a wellhead pressure somebody typed in, and on a real gathering system nobody types that pressure.'),
  ('network', 'beginner', 'final', null, 1, 'A wall rating and an equivalent length are worked for the same NPS 6 schedule 40 line. Which diameter goes into each?', '["Both take the bore of 6.065 in, since a pressure acts on the inside surface and a flow runs through the same surface.", "The rating takes the outside diameter of 6.625 in, because Barlow''s D is the outside diameter, and the equivalent length takes the bore of 6.065 in, because a length of pipe is a length of the hole.", "Both take the outside diameter of 6.625 in, since that is the dimension the schedule row is keyed on.", "The rating takes the bore and the length takes the outside diameter."]'::jsonb, 1, 'One row of the table supplies both, and the two closed forms in the file reach into it for different columns.'),
  ('network', 'beginner', 'final', null, 2, 'The design factor and the friction factor are both inputs the two closed forms decline to supply. What happens if each is left out?', '["Both refuse, since the module never defaults an input a jurisdiction or a pipe correlation is responsible for, and both sentences name the missing quantity.", "Both return NaN, in the way an unknown grade and an unknown fitting identifier do, so a caller who never tests for it carries either onward.", "A missing design factor returns the bare hoop stress of 4395.471698 psi, while a missing friction factor is a refusal saying an equivalent length needs a bore and a friction factor.", "Both default, the design factor to 0.72 and the friction factor to 0.018, which are the values the gate case runs at."]'::jsonb, 2, 'One of the two omissions is silent and gives a number 1.388889 times the rating, and the other one stops. That asymmetry sits inside a single file.'),
  ('network', 'beginner', 'final', null, 3, 'buildNetwork fails with ok false and a sentence. The pipe table fails with null or NaN. Which failure reaches a report without anybody noticing?', '["The ok false, since a caller who tests only the numeric returns will step straight past a refusal object and read the empty pressures beside it.", "The null, since a null in an arithmetic expression is treated as a zero and a zero bore produces a length rather than an error.", "None of the three, since every failure in both files is either an explicit refusal or a value that fails a numeric test at the first use.", "NaN, because it carries through arithmetic without complaint."]'::jsonb, 3, 'gradeYield(''x55''), fittingK(''elbow90''), roughnessOf(''nonsense'') and a zero wall all resolve to NaN, and a refusal at least says a sentence.'),
  ('network', 'beginner', 'final', null, 4, 'A fitting list on a flowline comes back as a length in ft. How does that length reach the network solve?', '["It does not. The pipe hydraulics along a branch are a callback the consumer supplies, and nothing in either file turns a length in ft into a branch relation.", "Through the branch conductance, which the solve forms from the equivalent length and the bore.", "Through the index, which carries the geometry of each branch alongside its two ends.", "Through diagnose, which reads the length back when it ranks a bottleneck."]'::jsonb, 0, 'The equivalent length is added to the measured run and the total goes to a pressure drop correlation this module does not own.'),
  ('network', 'beginner', 'final', null, 5, 'An NPS 6 schedule 40 line in X52 rates 3164.739623 psi and AGBADA-2''s solo run lands its wellhead at 892.889543025 psia. What has been established by putting the two side by side?', '["That the line is fit for the duty, since the rating is the pressure the line may be operated to and the wellhead is the pressure it will see.", "That the design factor of 0.72 is conservative for this service, because the wellhead sits so far under the rating that a higher factor would still be safe.", "That the well can be produced without a choke, since nothing between the wellhead and the separator reaches the rated pressure of the line.", "That one number is below the other, and nothing more, since a rating and a solved pressure come from two functions that never meet."]'::jsonb, 3, 'The rating carries no fluid, no temperature and no service, and the solved wellhead carries no pipe wall, so neither says anything about the other.'),
  ('network', 'beginner', 'final', null, 6, 'Which function produced the wellhead of 892.889543025 psia, and which produced the gap of 9.094947e-13 lb/d?', '["solveNetwork produced both, since the gap is reported in the same object as the pressures and the flags and comes out of the same Newton iteration that settled them.", "solveNetwork produced the wellhead and checkConservation produced the gap.", "buildNetwork produced the wellhead and solveNetwork the gap.", "diagnose produced both, since it is the function that reads an answer."]'::jsonb, 1, 'The gap only exists because somebody called the second function, and solveNetwork never calls it.'),
  ('network', 'beginner', 'final', null, 7, 'A solo run of one well carries 1 unknown pressure and AGBADA WEST carries 7. What sets each of those two counts?', '["The number of wells, since a well is the only node kind whose pressure is unknown and a junction takes the pressure of the branch that feeds it.", "The number of branches less the number of nodes, which is the number of independent flows the solve has to settle before the pressures follow from them.", "The number of nodes whose pressure nobody supplied, which is every node that is not a delivery point.", "The number of iterations."]'::jsonb, 2, 'AGBADA WEST has 8 nodes and 1 delivery point, and its unknown list is t1, t2, t3, t4, ha, hb, hc, which is three junctions as well as four wells.'),
  ('network', 'beginner', 'final', null, 8, 'A fitting list and a branch conductance both describe resistance on a line. Why can neither be turned into the other here?', '["Because an equivalent length is a length in ft on a named bore at a named friction factor, and a branch conductance is a mass per root psi handed in by the caller, and nothing in either file connects them.", "Because the two are quoted at different rates, so a conversion would need the mass on the line.", "Because a conductance is signed and an equivalent length is not.", "Because the fitting table publishes coefficients that vary between manufacturers."]'::jsonb, 0, 'The equivalence in the fitting file is between a resistance coefficient and a length of pipe, and it stops there.'),
  ('network', 'beginner', 'final', null, 9, 'The pipe table refuses a size it does not carry and buildNetwork refuses a node kind it does not have. What do the two refusals share?', '["Both come back as an object carrying ok false and a sentence naming the thing that was asked for, which is the single failure shape the whole package uses.", "Both are recoverable, since the caller can supply the missing row or the missing kind and rerun without changing anything else in the input.", "Both are warnings rather than refusals, because the drawing and the table are each still readable with the offending entry left out of them.", "Neither substitutes anything nearby, and each says so in the currency of its own file."]'::jsonb, 3, 'scheduleRow(5, ''40'') is null, and Node "K-1" has kind "compressor", which is not one of well, junction, sink.'),
  ('network', 'beginner', 'final', null, 10, 'An equivalent length calculation meets one unknown fitting identifier, and buildNetwork meets one branch whose end does not resolve. What does each do with the rest of its input?', '["The fitting calculation drops the unknown entry and reports a length with a warning, while the build refuses, because a missing coefficient is smaller than a missing node.", "Neither prices or indexes any of it. Both refuse whole rather than dropping the offending term.", "Both continue and mark the entry, since a partial answer is more useful than none.", "Both substitute a default and record the substitution in the returned object."]'::jsonb, 1, 'Dropping a term would quietly understate a list, and indexing around a branch would quietly change the topology.'),
  ('network', 'beginner', 'final', null, 11, 'The Associate order says to build before you solve. What does the build hand across?', '["A first estimate of every unknown pressure, formed from the boundary pressure and the branch conductances, which the solve then refines by Newton.", "The branch relations, which the build assembles from the drawing and the pipe geometry and passes to the solve as a system of equations.", "Node and branch counts, a delivery point count and an index of the unknowns in the order t1, t2, t3, t4, ha, hb, hc, with no pressure computed anywhere in it.", "Nothing but a flag."]'::jsonb, 2, 'buildNetwork validates and indexes and will never compute a pressure, so what it hands over is a table rather than an answer.'),
  ('network', 'beginner', 'final', null, 12, 'The order says to record each well''s solo wellhead, rate and line drop before the wells are solved together. What does that buy?', '["A set of initial guesses for the system solve, which is what makes the later iteration converge in a handful of steps rather than running its cap.", "A calibration for the branch conductances, since a solo line drop against a solo rate is what a turbulent conductance is fitted from in the first place.", "A check on the system answer, since the solo rates have to add to what the system produces once the header rise has been taken off each of them.", "A price for what the network did, which nothing in the system answer carries on its own."]'::jsonb, 3, 'The four AGBADA solo rates add to 15683.052292561 lb/d against a system total of 13300.677150912 lb/d, which is 15.190761959 percent.'),
  ('network', 'beginner', 'final', null, 13, 'The teaching NPS 8 schedule 80 line carries a rating and a fitting list. Which of its published dimensions does each use?', '["The outside diameter of 8.625 in and the wall of 0.5 in give the rating of 5426.086957 psi, and the bore of 7.625 in gives the 540.104167 ft.", "The bore of 7.625 in serves both, since it is the dimension the line is specified by.", "The wall of 0.5 in serves both, once through Barlow and once through the bore it implies.", "The outside diameter of 8.625 in serves both."]'::jsonb, 0, 'One row of the table feeds two closed forms, and they reach for different columns of it.'),
  ('network', 'beginner', 'final', null, 14, 'solveNetwork reports pinned t4 on the teaching network and buildNetwork reported ok true on the same drawing. Which of the two is a statement about the drawing?', '["The pinned t4, since a node is pinned when nothing in the drawing gives it a route by which its pressure could matter, which is a topology fact rather than a numerical one.", "The ok true, which says the drawing could be indexed.", "Both, since a pinned node is refused at build time on any drawing that carries one.", "Neither, since both are produced after the pressures are known."]'::jsonb, 1, 'A pinned node is a fact about the answer, and the build had computed no pressure when it said ok true.'),
  ('network', 'beginner', 'final', null, 15, 'W-1 makes 2242.495611803 lb/d with one companion and 2007.745062176 lb/d with two, a loss of 10.468272 percent, against W-0''s 10.919052 percent. What does the pair of figures show?', '["That the loss is a constant fraction of a well''s rate, so a deferment can be estimated from the number of wells on a header without solving anything.", "That W-1 is the stronger of the two, since it kept more of itself, and that ranking wells by percentage lost ranks them by strength.", "That every well already on the header gives something up when another arrives, in shares that are close but not equal.", "That the two losses are the same number within the tolerance the golden case was committed at."]'::jsonb, 2, 'The header climbed 416.314057 psi across the ladder, and what each well gives up depends on the margin it had over the header before the rise.'),
  ('network', 'beginner', 'final', null, 16, 'The teaching network solve reports 11 iterations. What does an iteration count establish about the answer?', '["How much work the iteration did, and nothing at all about whether mass balances at the end of it.", "That the solve met its tolerance, since a run that did not meet it would have gone on to the module cap of 200 before returning.", "That the Jacobian was well conditioned, since a poor one costs more steps.", "That the answer is within 11 times the tolerance of the true solution."]'::jsonb, 0, 'The same run reports a gap of 345.000000000 lb/d under a residual of 1.546141e-11 lb/d, and the iteration count is silent about both.'),
  ('network', 'beginner', 'final', null, 17, 'DEFAULT_MAX_ITER is 200. What is it?', '["The number of steps the module runs before it reports, which is why every solve of every network returns the same iteration count on the same tolerance.", "A cap on the number of Newton steps, and hitting it is one of the three conditions the module warns about rather than refusing.", "A cap on the line search backtracks within one step.", "The number of nodes the module can index."]'::jsonb, 1, 'The teaching network needs 11 of them and the solo runs need 7, so the cap is nowhere near the working range.'),
  ('network', 'beginner', 'final', null, 18, 'diagnose reports a bottleneck, a biggest drop, backflows and dead legs. What does it need before it can report any of them?', '["A conservation gap, since a bottleneck is only meaningful once the mass that failed to arrive has been attributed to the branch that failed to pass it.", "The pipe geometry of every branch, since a bottleneck is a statement about a line and the solve carries only conductances and flows.", "The unknown index in the order the solve used, since a ranking has to be reported against the same node order the pressures came back in.", "A solved answer, because it reads one rather than computing anything itself."]'::jsonb, 3, 'It is the reading rather than the solve, and the reading is one of the six functions in these two files.'),
  ('network', 'beginner', 'final', null, 19, 'The teaching network''s trunk carries 12955.677150912 lb/d and checkConservation reports produced 13300.677150912 lb/d. Which figure is what the delivery point took?', '["The 13300.677150912 lb/d, since produced and delivered are the same quantity read at two ends and the larger figure is the one measured at the boundary.", "Neither, since the delivered figure is the sum of the four well rates and the trunk carries only what the loop legs merged into it.", "The 12955.677150912 lb/d on the trunk, which is the delivered side of the comparison.", "Both, at different pressures."]'::jsonb, 2, 'The two differ by 345.000000000 lb/d, and the gap is the whole content of the comparison.'),
  ('network', 'beginner', 'final', null, 20, 'Across the four sizes the table ships in both schedules, the flow area lost between schedule 40 and schedule 80 runs from 8.722219 to 12.001622 percent. Which size loses the most?', '["NPS 8, at 12.001622 percent, because the largest of the four carries the thickest wall and therefore gives up the most metal into the bore.", "NPS 2, at 12.001622 percent, on a bore lost of 0.128000 in.", "NPS 6, because it is the one row of the twelve that fails strict equality.", "They are equal, since a schedule is a proportion."]'::jsonb, 1, 'The smallest size gives up the smallest bore in inches and the largest share of its area, because area follows the square of what is left.'),
  ('network', 'beginner', 'final', null, 21, 'A rating is quoted at a design factor of 1. What is it?', '["The hoop stress at yield, 7536.231884 psi on the teaching line, which describes a wall about to fail rather than a pressure to work to.", "The rating of the strongest grade the module ships, which is x65 at 65000 psi.", "The rating with the corrosion allowance removed from the wall.", "A refusal, since a design factor of 1 is outside the range codes allow."]'::jsonb, 0, 'It is the same calculation with the factor doing nothing, and it is what comes back when no factor is supplied at all.'),
  ('network', 'beginner', 'final', null, 22, 'A rating arrives on a drawing with no design factor written beside it. What can be done with it?', '["It can be compared with any other rating on the same size and grade, since the design factor cancels out of a comparison between two pipes of the same steel.", "It can be converted to a bare hoop stress by dividing by 1.388889, which is the ratio the gate case gives between the two.", "It can be read as the rating at a design factor of 0.72, since that is the value the gate case uses and the one most codes settle on.", "Nothing, because two ratings are only comparable when the factor behind them is the same number."]'::jsonb, 3, 'The gap between two ratings may be steel, wall, diameter or a jurisdiction, and the rating carries none of them.'),
  ('network', 'beginner', 'final', null, 23, 'Barlow is linear in the wall the table publishes. What sort of wall is that?', '["The wall of a pipe that has never been in service, since no corrosion allowance is an input anywhere in the calculation.", "The minimum wall after the mill tolerance has been taken off it.", "The mean wall around the circumference of the pipe.", "The wall at the moment the rating was requested."]'::jsonb, 0, 'Metal lost off the inside comes off the rating in proportion, and doubling the gate wall to 0.56 in doubles its rating to 6329.479245 psi.'),
  ('network', 'beginner', 'final', null, 24, 'The closeness test at three decimals is the loosest assertion in the gate file. What else stands behind the pipe table?', '["The oracle, which imports the table when it builds the branch relations for each of its four published cases and therefore exercises every row of it.", "The redundancy itself, which the module runs at load time and reports on, independently of whatever the gate asserts about it.", "Nothing. There is no Python referee for that module anywhere.", "The goldens, which carry a bore for every branch."]'::jsonb, 2, 'The band admits a bore typed as 6.0654 in against a published 6.065 in, which is a larger error than the redundancy exists to catch.'),
  ('network', 'beginner', 'final', null, 25, 'Which entry in the published fitting table reaches double figures?', '["The swing check at 2, which is the largest coefficient on the list once the exit into a vessel is counted as a boundary rather than as a fitting.", "The branch tee at 1, which is the largest because a tee taken on the branch turns the whole of the flow through a right angle.", "None of them, since the coefficients are approximations and the table keeps every entry below the point where a single fitting could dominate a list.", "The fully open globe valve, at 10."]'::jsonb, 3, 'A fully open ball valve is 0.05 on the same bore with nothing else different, and that spread is why a fitting count is never a detail.'),
  ('network', 'beginner', 'final', null, 26, 'An equivalent length is added to the measured run of a line. What happens to the total?', '["It is converted to a pressure drop inside the module, using the friction factor that was supplied for the equivalent length in the first place.", "It becomes the branch length the solve uses, since a branch relation is built from a length and a bore before the network is assembled.", "It goes to a pressure drop correlation, which this module does not own and never calls.", "It is returned in ft and in psi."]'::jsonb, 2, 'The file returns a sum of resistance coefficients and a length in ft, and that is the whole of its output.'),
  ('network', 'beginner', 'final', null, 27, 'A datasheet says a long radius elbow is worth a fixed number of feet. What is missing from that statement?', '["The bore and the friction factor of the line it was worked on, because the same six fittings run 14.354167 ft on a 2.067 in bore and 104.166667 ft on a 15 in bore.", "The number of elbows, since a coefficient is per fitting and a length is for a list.", "The schedule, since the outside diameter is what a length is scaled on.", "The rate, since a fitting loss is quoted at a reference velocity."]'::jsonb, 0, 'The fitting is the only part of that figure that travels, and everything else in it describes one particular pipe.'),
  ('network', 'beginner', 'final', null, 28, 'The published list is 54.151786 ft and 107.142857 diameters at a friction factor of 0.014, and 30.325000 ft and 60.000000 diameters at 0.025. Which of those four numbers belongs to the fittings alone?', '["The two diameter counts, since expressing a length in diameters divides the bore out of it and leaves a figure that describes the fittings.", "The two lengths, since a length in ft is the physical quantity and the diameter counts are only a way of restating it on a particular bore.", "All four, since the fitting list is the only thing held fixed across the two rows and everything that moved was computed from it.", "None of them. Only the sum of resistance coefficients belongs to the fittings."]'::jsonb, 3, 'Every one of the four is a function of the friction factor, which is a property of the pipe and not of the elbows or the valves on it.'),
  ('network', 'beginner', 'final', null, 29, 'Why are the published resistance coefficients round numbers?', '["Because they are ratios of small integers, which is what a velocity head count is, and the table therefore prints them exactly rather than rounding anything.", "Because they are approximations that vary between manufacturers, and three decimals would suggest a precision that does not exist.", "Because a rounded coefficient keeps the sum of a list exact in floating point.", "Because they were fitted on one bore and rounded when they were carried to the others."]'::jsonb, 1, 'The module is exact about the inputs it demands and honest about the precision of what it publishes.'),
  ('network', 'beginner', 'final', null, 30, 'AGBADA WEST has 8 nodes and 8 branches. What does the branch count on a given node tell you?', '["How many unknown pressures that node contributes to the index, since each branch on a node carries one pressure at its far end that has to be solved for.", "How many times the node appears in the Jacobian, which is what sets the bandwidth of the dense linear solve and therefore the cost of a step.", "How many routes that node has to the delivery point, which is what the build checks when it looks for a stranded node.", "How many terms that node''s mass balance has."]'::jsonb, 3, 'Five flows have to add to nothing at the north manifold, and a well''s balance is its inflow against its single flowline.'),
  ('network', 'beginner', 'final', null, 31, 'Removing which branch of AGBADA WEST would leave a node with no route to the delivery point?', '["Any of the four flowlines, which strands the well on the far end of it, or the trunk, which is the only branch on the separator.", "Any of the three loop branches, since a junction with a branch removed cannot balance.", "The crosslink, which is the only route the loop tee has.", "None of the eight, since every node carries more than one branch."]'::jsonb, 0, 'The north manifold reaches the trunk tee straight down the north bypass and again through the crosslink and the loop leg, so a loop branch costs a path the network has another of.'),
  ('network', 'beginner', 'final', null, 32, 'A test separator that chokes back and swings has to be represented. Where does it go?', '["Into the sink, whose fixed pressure is set to the average the test separator swings about, with the swing carried as a warning on the answer.", "Into a junction, since a junction injects nothing and everything arriving leaves, which is what a separator does between one swing and the next.", "Nowhere in this module. A sink accepts whatever arrives at a fixed pressure and that is the whole of what a sink does.", "Into the boundary list."]'::jsonb, 2, 'Anything a real gathering system has that is not a well, a junction or a sink has to be written as a branch relation or left out and said so.'),
  ('network', 'beginner', 'final', null, 33, 'Why is the unknown order also the column order the linear solve works in?', '["Because the branches are indexed in the same pass and their signs are taken from the order the nodes were read in, which is what makes the assembly consistent.", "Because each unknown node contributes one mass balance, so the index is both the list of equations and the list of pressures.", "Because the dense solve pivots on the largest entry and the order is chosen to put it first.", "Because the drawing lists the wells before the junctions."]'::jsonb, 1, 'The solve on AGBADA WEST is 7 equations in 7 pressures, and reversing the node array moves the unpinned pressures by at most 1.1369e-13 psia.'),
  ('network', 'beginner', 'final', null, 34, 'A node is renamed between the build and the read. What happens?', '["The build is invalidated and the next call refuses, because the index carries the identifiers it was built with and a mismatch is one of the eleven refusals.", "Nothing at all, because the solve works on array positions rather than identifiers and the identifiers are only used when the answer is printed.", "The rename separates a pressure from the node it belongs to, and nothing complains.", "The node is treated as a new one."]'::jsonb, 2, 'The index is keyed on the id, which is also why two nodes sharing the id "w" is refused before anything else happens.'),
  ('network', 'beginner', 'final', null, 35, 'Rank the four AGBADA flowlines by conductance and then by the drop each one pays. Why do the two rankings differ?', '["Because a conductance in lb/d per root psi and a drop in psi are different quantities, so no ranking by one can be expected to agree with a ranking by the other at all.", "Because a drop depends on the mass the line is carrying as well as on the line itself.", "Because the conductances were fitted at different rates.", "Because one of the four lines is capacity limited."]'::jsonb, 1, 'AGBADA-6 is the slackest at 365 lb/d per root psi and pays 70.147329090 psi, while AGBADA-9 at 198 lb/d per root psi pays 575.553310094 psi.'),
  ('network', 'beginner', 'final', null, 36, 'AGBADA-12''s solo line drop of 38.714448989 psi sits beside a reported rate of 985.000000000 lb/d. Why is that row not a like for like with the other three?', '["Because its conductance of 126 lb/d per root psi is the smallest of the four, so its drop is not comparable with drops taken on slacker lines at higher rates.", "Because its wellhead of 303.714448989 psia is the lowest of the four and a drop measured that close to the boundary is dominated by the boundary pressure itself.", "Because the other three were solved in 7 iterations and this one in 4, so its drop was taken from a different point in the iteration than theirs were.", "Because the drop was formed on the 640.000000000 lb/d the line actually passes, while the rate beside it is the allocation."]'::jsonb, 3, 'The drop and the rate on that line are not describing the same mass, and the difference is 3.450000e+2 lb/d.'),
  ('network', 'beginner', 'final', null, 37, 'What does a wellhead pressure mean in this module?', '["Whatever the inflow callback and the branch callback both take it to mean, because the module supplies neither of them and records no depth against the answer.", "The pressure at the tree, measured on the upstream side of the wing valve.", "The pressure at the point where the tubing meets the flowline.", "The pressure at the top of the completion, above the wellhead choke."]'::jsonb, 0, 'The only opinion the module has about that number is that it may not sit below MIN_PRESSURE_PSIA of 14.7 psia.'),
  ('network', 'beginner', 'final', null, 38, 'A wellhead pressure is read off a gauge and the inflow curve is evaluated at it. What question has been answered?', '["Where the wellhead lands, since a gauge reading and a solved pressure are the same quantity and using the measured one removes an iteration.", "What the well makes on the system, since a gauge on a live gathering system is already reading the header the well is fighting and carries the fight in it.", "What the well would make if the wellhead sat there, which is not where the wellhead sits.", "Nothing, since an inflow curve cannot be evaluated at a supplied pressure."]'::jsonb, 2, 'With the wellhead supplied there is no unknown left, and the rate that comes back is the rate at the pressure that was assumed.'),
  ('network', 'beginner', 'final', null, 39, 'The Associate order closes on a list of units. What is the pair it says never compare?', '["A mass rate in lb/d against a surface volume in stb/d, since the two describe the same stream and only differ by a density the module does not carry anywhere.", "A turbulent branch conductance in lb/d per root psi against a linear branch conductance in lb/d per psi.", "An absolute pressure in psia against a wall rating in psi.", "A bore in in against an equivalent length in ft."]'::jsonb, 1, 'Mass is the currency, absolute pressure is psia and never psig, and a difference and a rating are both in psi.'),
  ('network', 'beginner', 'final', null, 40, 'The order says to report the converged flag, the pinned list and the conservation gap together. Why together?', '["Because a flag on its own is not a result, and the gap is the only one of the three that was not produced by the iteration that produced the answer.", "Because the three are returned in one object and splitting them would lose the pinned list.", "Because a pinned node is what makes a gap possible, so neither reads without the other.", "Because the gap is the number the flag is tested against."]'::jsonb, 0, 'Wherever a lesson prints an answer out of the solve it also says what was checked and what was not, which is the most transferable habit in the course.'),
  ('network', 'beginner', 'final', null, 41, 'Which of the tier''s four questions catches a reported residual of 1.546141e-11 lb/d being read as a check on the answer?', '["What unit it is in, since the residual is quoted in lb/d and a check on an answer has to be quoted in the units of the quantity it is checking rather than of the balance.", "Which of the six functions produced it, since a number that came out of solveNetwork is by construction a statement about the network rather than about the iteration.", "Whether the function that produced it had a way to refuse, since a function that can refuse and did not has thereby asserted that its answer is sound.", "What checked it that was not the iteration that made it."]'::jsonb, 3, 'checkConservation on the same answer reports 345.000000000 lb/d, and solveNetwork never calls it.'),
  ('network', 'beginner', 'final', null, 42, 'The tier says a converged flag and a conservation gap can both be true of the same answer. Why is that not a contradiction?', '["Because the flag is tested against a target the caller asked for while the gap is tested against a target the module computes, so the two thresholds are simply set differently.", "Because they measure different things, and only one of them was computed by something other than the iteration.", "Because the flag describes the pressures and the gap describes the flows.", "Because the gap is reported to more digits than the flag is tested at."]'::jsonb, 1, 'AGBADA-12 alone reports a residual of 0.0000e+0 lb/d and a gap of 3.450000e+2 lb/d, relative 3.502538e-1.');
